import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import TabBar from "../../components/common/TabBar";
import BookingTile from "../../components/common/BookingTile";
import api from "../../utils/api";
import errorImage from "../../images/errorLoading.png";
import Popup from "../../components/common/Popup";
import RatingPopup from "../../components/common/RatingPopup"; // ⭐ NEW

/* ---------- Styled Components ---------- */

const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 40px 0;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 60px;
`;

const Section = styled.div`
  width: 100%;
`;

const SectionTitle = styled.h2`
  font-family: "Inter", sans-serif;
  font-size: 36px;
  font-weight: 800;
  color: #27374d;
  margin-bottom: 25px;
`;

const TilesContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 25px;
`;

/* ---------- Types ---------- */

type ServiceDto = {
  _id: string;
  name: string;
  durationMinutes: number;
  priceBHD: number;
  description?: string;
};

type BusinessDto = {
  _id: string;
  businessName: string;
  address: string;
  city: string;
  imageUrl?: string;
};

type BookingDto = {
  _id: string;
  business: BusinessDto;
  services: ServiceDto[];
  startTime: string;
  endTime: string;
  status: "pending" | "confirmed" | "cancelled" | "completed";
};

type BookingListItem = {
  id: string;
  bookingId: string;
  businessId: string;
  date: string;
  image: string;
  businessName: string;
  location: string;
  services: string[];
  servicesFull: ServiceDto[];
  totalDuration: number;
  totalPrice: number;
  status: "upcoming" | "past" | "cancelled";
};

/* ---------- Component ---------- */

const BookingsPage: React.FC = () => {
  const navigate = useNavigate();

  const [upcoming, setUpcoming] = useState<BookingListItem[]>([]);
  const [past, setPast] = useState<BookingListItem[]>([]);
  const [loading, setLoading] = useState(true);

  const [showCancelPopup, setShowCancelPopup] = useState(false);
  const [bookingIdToCancel, setBookingIdToCancel] = useState<string | null>(null);

  // ⭐ Rating popup states
  const [showRatingPopup, setShowRatingPopup] = useState(false);
  const [selectedBusinessId, setSelectedBusinessId] = useState<string | null>(null);

  /* ---------- Load Bookings ---------- */

  const loadBookings = async () => {
    try {
      setLoading(true);
      const res = await api.get<BookingDto[]>("/bookings/me");
      const bookings = res.data || [];

      const now = new Date();
      const upcomingList: BookingListItem[] = [];
      const pastList: BookingListItem[] = [];

      bookings.forEach((b) => {
        const start = new Date(b.startTime);

        let tileStatus: "upcoming" | "past" | "cancelled";
        if (b.status === "cancelled") tileStatus = "cancelled";
        else if (start > now) tileStatus = "upcoming";
        else tileStatus = "past";

        const businessName = b.business?.businessName || "Salon";
        const location = b.business ? `${b.business.address}, ${b.business.city}` : "";

        const totalDuration = b.services.reduce((sum, s) => sum + (s.durationMinutes || 0), 0);
        const totalPrice = b.services.reduce((sum, s) => sum + (s.priceBHD || 0), 0);

        const item: BookingListItem = {
          id: b._id,
          bookingId: b._id,
          businessId: b.business?._id,
          date: start.toLocaleString("en-US", {
            weekday: "short",
            year: "numeric",
            month: "short",
            day: "numeric",
            hour: "numeric",
            minute: "numeric",
          }),
          image: b.business?.imageUrl
            ? `http://localhost:5000${b.business.imageUrl}`
            : errorImage,
          businessName,
          location,
          services: b.services.map((s) => s.name),
          servicesFull: b.services,
          totalDuration,
          totalPrice,
          status: tileStatus,
        };

        if (tileStatus === "upcoming") upcomingList.push(item);
        else pastList.push(item);
      });

      setUpcoming(upcomingList);
      setPast(pastList);
    } catch (err) {
      console.error("Error loading bookings:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadBookings();
  }, []);

  /* ---------- Cancel Booking ---------- */

  const handleCancelClick = (id: string) => {
    setBookingIdToCancel(id);
    setShowCancelPopup(true);
  };

  const confirmCancel = async () => {
    if (!bookingIdToCancel) return;

    try {
      await api.patch(`/bookings/${bookingIdToCancel}`, { action: "cancel" });
      setShowCancelPopup(false);
      setBookingIdToCancel(null);
      loadBookings();
    } catch (err: any) {
      console.error("Cancel booking error:", err);
      alert(err?.response?.data?.message || "Failed to cancel booking.");
    }
  };

  const cancelPopupSecondary = () => {
    setShowCancelPopup(false);
    setBookingIdToCancel(null);
  };

  /* ---------- Reschedule ---------- */

  const handleRescheduleClick = (booking: BookingListItem) => {
    navigate("/book/select-date", {
      state: {
        isReschedule: true,
        bookingId: booking.bookingId,
        businessId: booking.businessId,
        businessName: booking.businessName,
        selectedServices: booking.servicesFull,
        totalDurationMinutes: booking.totalDuration,
        totalPrice: booking.totalPrice,
      },
    });
  };

  /* ---------- Submit Rating ---------- */

  const submitReview = async (rating: number, comment: string) => {
    if (!selectedBusinessId) return;

    try {
      await api.post("/reviews", {
        businessId: selectedBusinessId,
        rating,
        comment,
      });

      alert("Thank you! Your review has been submitted.");
      setShowRatingPopup(false);
      setSelectedBusinessId(null);
    } catch (err) {
      console.error(err);
      alert("Failed to submit review.");
    }
  };

  /* ---------- Loading State ---------- */

  if (loading) {
    return (
      <PageWrapper>
        <TabBar type="customer" />
        <ContentWrapper>
          <SectionTitle>Loading your bookings…</SectionTitle>
        </ContentWrapper>
      </PageWrapper>
    );
  }

  /* ---------- Render ---------- */

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>

        {/* UPCOMING */}
        <Section>
          <SectionTitle>Upcoming Bookings</SectionTitle>
          <TilesContainer>
            {upcoming.length === 0 && <p>No upcoming bookings.</p>}

            {upcoming.map((booking) => (
              <BookingTile
                key={booking.id}
                id={booking.id}
                date={booking.date}
                image={booking.image}
                businessName={booking.businessName}
                location={booking.location}
                services={booking.services}
                status={booking.status}
                onCancel={() => handleCancelClick(booking.id)}
                onReschedule={() => handleRescheduleClick(booking)}
                onViewReceipt={() => navigate(`/book/receipt/${booking.id}`)}
              />
            ))}
          </TilesContainer>
        </Section>


        {/* PAST */}
        <Section>
          <SectionTitle>Past Bookings</SectionTitle>
          <TilesContainer>
            {past.length === 0 && <p>No past bookings.</p>}

            {past.map((booking) => (
              <BookingTile
                key={booking.id}
                id={booking.id}
                date={booking.date}
                image={booking.image}
                businessName={booking.businessName}
                location={booking.location}
                services={booking.services}
                status={booking.status}
                onViewReceipt={() => navigate(`/book/receipt/${booking.id}`)}
                onLeaveRating={() => {
                  setSelectedBusinessId(booking.businessId);
                  setShowRatingPopup(true);
                }}
              />
            ))}
          </TilesContainer>
        </Section>

      </ContentWrapper>

      {/* CANCEL POPUP */}
      {showCancelPopup && (
        <Popup
          title="Cancel Booking"
          description="Are you sure you want to cancel this booking?"
          primaryLabel="Yes, cancel"
          secondaryLabel="No, keep it"
          onPrimary={confirmCancel}
          onSecondary={cancelPopupSecondary}
        />
      )}

      {/* ⭐ RATING POPUP */}
      {showRatingPopup && selectedBusinessId && (
        <RatingPopup
          businessId={selectedBusinessId}
          onClose={() => setShowRatingPopup(false)}
          onSubmit={submitReview}
        />
      )}
    </PageWrapper>
  );
};

export default BookingsPage;
